window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"c96uVNixulU","speaker":"Julius Maada Bio","role":"President","country":"Sierra Leone","region":"Africa","url":"https://www.youtube.com/watch?v=c96uVNixulU","date":"20260922","title":"🇸🇱 Sierra Leone - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1307,"words":1967,"counts":{"claims":33,"promises":2,"attacks":0},"topics":[{"topic":"UN Security Council reform","share":0.1615,"seconds":211},{"topic":"UN reform","share":0.0985,"seconds":129},{"topic":"Syria","share":0.0641,"seconds":84},{"topic":"DRC conflict","share":0.0563,"seconds":74},{"topic":"Palestine-Israel","share":0.0535,"seconds":70},{"topic":"Africa minerals","share":0.0533,"seconds":70},{"topic":"International law","share":0.0513,"seconds":67},{"topic":"UN trust","share":0.051,"seconds":67},{"topic":"African reparations","share":0.051,"seconds":67},{"topic":"Reparatory justice","share":0.0506,"seconds":66},{"topic":"Child marriage","share":0.0499,"seconds":65},{"topic":"Sierra Leone peace","share":0.0486,"seconds":64},{"topic":"UN leadership","share":0.048,"seconds":63},{"topic":"Climate finance","share":0.0471,"seconds":62},{"topic":"AI development","share":0.047,"seconds":61},{"topic":"UN Security Council","share":0.0469,"seconds":61},{"topic":"Ceremony","share":0.0214,"seconds":28}],"timeline":[[5,75,null],[78,140,"UN leadership"],[144,207,"Sierra Leone peace"],[209,276,"UN trust"],[279,346,"International law"],[353,423,"Palestine-Israel"],[427,501,"DRC conflict"],[503,564,"UN Security Council"],[567,633,"UN Security Council reform"],[637,712,"UN Security Council reform"],[715,785,"UN Security Council reform"],[789,855,"African reparations"],[858,924,"Reparatory justice"],[925,994,"Africa minerals"],[995,1060,"Child marriage"],[1062,1123,"AI development"],[1125,1187,"Climate finance"],[1189,1255,"UN reform"],[1260,1344,"Syria"],[1345,1408,"UN reform"],[1413,1441,"Ceremony"]],"stances":{"UN leadership":"Julius Maada Bio expresses gratitude and commendation for the Secretary-General and Deputy Secretary-General for their service to the United Nations.","Sierra Leone peace":"Julius Maada Bio states that the United Nations supported Sierra Leone's transition from conflict to peace through disarmament and institution rebuilding, emphasizing that trust is built by honoring promises rather than declarations.","UN trust":"Julius Maada Bio states that trust in international institutions is currently under strain and emphasizes the moral weight of ensuring the UN acts for all people.","International law":"Julius Maada Bio argues that international law must be applied universally without bias based on geography or the identity of the accused, and that it should protect the vulnerable as firmly as it restrains the powerful.","Palestine-Israel":"Julius Maada Bio calls for the protection of civilians, an end to aggression and occupation, and the realization of Palestinian self-determination through a viable state living alongside Israel.","DRC conflict":"Julius Maada Bio states that military action alone cannot build lasting peace and emphasizes the need to link peace efforts with development funding.","UN Security Council":"Julius Maada Bio argues that the current composition of the UN Security Council is outdated and unfair because it does not reflect the modern world or Africa's demographic weight.","UN Security Council reform":"Julius Maada Bio asserts that the UN Security Council lacks legitimacy without African representation and calls for specific permanent and non-permanent seats for Africa.","African reparations":"Julius Maada Bio asserts that restoring trust requires addressing the unfinished cause of reparatory justice for the enslavement of Africans.","Reparatory justice":"Julius Maada Bio asserts that reparatory justice is a necessary call for redress and non-discrimination rather than charity, emphasizing Sierra Leone's solidarity with Africa and the diaspora in this cause.","Africa minerals":"Julius Maada Bio argues that Africa's critical minerals must be processed locally to create jobs and prevent youth vulnerability, rather than being exported as raw materials.","Child marriage":"Julius Maada Bio states that Sierra Leone has enacted laws prohibiting child marriage and is working to eliminate it through domestic policies.","AI development":"Julius Maada Bio states that artificial intelligence can improve key sectors but warns it may widen inequality if standards are not shaped by developing nations.","Climate finance":"Julius Maada Bio argues that accessible climate finance and support for adaptation are obligations of justice, particularly for those who contributed least to the crisis.","UN reform":"Julius Maada Bio supports UN reforms to improve effectiveness and accountability, and calls for the selection of a woman as the next Secretary-General to demonstrate institutional equality.","Syria":"Julius Maada Bio emphasizes the importance of a capable United Nations based on Syria's experience and outlines Syria's continued commitment to peace operations, international law, and supporting international justice institutions.","Ceremony":"Julius Maada Bio expresses gratitude and acknowledges the theme of the year as a measure of work."},"claims":[{"t":78,"quote":"He has Syrian's full support. I pay tribute to his excellency secretary general Antonio Gutirez who is in the closing months of his He has served this organization with moral clarity and the courage to speak difficult truths.","topic":"UN leadership","kind":"fact"},{"t":108,"quote":"I also commend her excellency Amina J. the deputy secretary general, for her exemplary service and distinguished representation of Africa on the global Mr. President, nearly 25 years ago, Srielon completed disarmament and formally declared its civil war over.","topic":"UN leadership","kind":"self_credit"},{"t":174,"quote":"the United Nations stood with us through disarmament, and the long work of peace building","topic":"Sierra Leone peace","kind":"fact"},{"t":226,"quote":"trust between nations in institutions and in multilateral cooperation is under profound strain","topic":"UN trust","kind":"fact"},{"t":320,"quote":"Trust is gained when the law protects the vulnerable as firmly as it restrains the powerful.","topic":"International law","kind":"fact"},{"t":329,"quote":"International law must not change with geography or bend according to the identity of the accused.","topic":"International law","kind":"fact"},{"t":353,"quote":"Civilians must be protected, humanitarian access ensured, aggression and occupation ended, and freedom of navigation safeguarded.","topic":"Palestine-Israel","kind":"fact"},{"t":395,"quote":"In Sudan, civilians continue to endure endure atrocities and displacement, underscoring the cost of delayed action.","topic":"Palestine-Israel","kind":"fact"},{"t":487,"quote":"In 2025, global military expenditure reached about 2.9 trillion United State dollars, the 11th consecutive annual increase.","topic":"DRC conflict","kind":"number"},{"t":545,"quote":"The Security Council still reflects the world of 1945.","topic":"UN Security Council","kind":"fact"},{"t":552,"quote":"Africa, home to more than 1.6 billion people and the subject of most of the council's work, still has no permanent","topic":"UN Security Council","kind":"fact"},{"t":567,"quote":"Africa seeks its rightful place because the council cannot be fully legitimate or effective while an entire continent remains permanently absent from its highest level of decision","topic":"UN Security Council reform","kind":"fact"},{"t":601,"quote":"The common African position espoused in Ezinia consensus and such declaration calls for no fewer than two permanent seats with all the rights and privileges of permanent membership including the veto if it is retained and five non-permanent seats","topic":"UN Security Council reform","kind":"fact"},{"t":667,"quote":"During our time on the security council in 2024 2025, we worked as a voice of reason and a bridge across division.","topic":"UN Security Council reform","kind":"fact"},{"t":679,"quote":"We convened the Security Council's first high level debate on redressing historical injustice against Africa, placed conflict related food insecurity at the center of its agenda, and with Guyana co-drafted unanimously adopted resolution 2807 on youth peace and security, strengthening young people's role in conflict prevention and peace building.","topic":"UN Security Council reform","kind":"self_credit"},{"t":726,"quote":"The imbalance within the security council is also present in international financial institutions whose structures still bear the imprint of an earlier","topic":"UN Security Council reform","kind":"fact"},{"t":766,"quote":"Srielion therefore supports a UN framework convention on international tax cooperation through Echos serum we champion a development system that responds more effectively to Africa's priorities.","topic":"UN Security Council reform","kind":"self_credit"},{"t":802,"quote":"In March, this assembly adopted a resolution led by Ghana and supported by the African Union and Caribbean community recognizing the trafficking and racialized charter enslavement of Africans as the gravest crime against","topic":"African reparations","kind":"fact"},{"t":834,"quote":"From Bones Island in our own river estuary, thousands of Africans were forcibly transported across the Atlantic into enslavement.","topic":"African reparations","kind":"fact"},{"t":858,"quote":"This history is woven into our national the consequences did not end with Their legacy continues to be reflected in enduring disparities in wealth, power, and opportunity across our world.","topic":"Reparatory justice","kind":"fact"},{"t":906,"quote":"Sriraelon stands with Africa, the Caribbean, and the wider African diaspora in advancing this cause","topic":"Reparatory justice","kind":"fact"},{"t":933,"quote":"Critical minerals are indispensable to the global energy transition.","topic":"Africa minerals","kind":"fact"},{"t":938,"quote":"Yet too much value is still added Processing at source, fear value chains, technology transfer, and local industry would turn natural wealth into ski work, stronger economies, and hope for our young people.","topic":"Africa minerals","kind":"fact"},{"t":1033,"quote":"In 2024, we enacted the prohibition of child marriage act and subsequently championed the proclamation of 27 November as the international day for the elimination of child Ali and forced marriage.","topic":"Child marriage","kind":"fact"},{"t":1097,"quote":"Artificial intelligence can improve of course education, health, agriculture and public administration.","topic":"AI development","kind":"fact"},{"t":1105,"quote":"It can also widen the inequality if infrastructure, knowledge and rule making remains concentrated in a few","topic":"AI development","kind":"fact"},{"t":1136,"quote":"In Shen on Srielon's southern coast, families watch the sea take their land, fishing grounds and the graves of their For them, climate change is the disappearance of home in the present.","topic":"Climate finance","kind":"fact"},{"t":1154,"quote":"Those who contributed least to the climate crisis are bearing some of its gravest greatest cost.","topic":"Climate finance","kind":"fact"},{"t":1223,"quote":"In 80 years, every Secretary General has been a man.","topic":"UN reform","kind":"fact"},{"t":1269,"quote":"This organization is part of our living history. It stood with us when our country was broken and helped us make peace durable.","topic":"Syria","kind":"fact"},{"t":1281,"quote":"In this hall, a small state has the same vote as a great power.","topic":"Syria","kind":"fact"},{"t":1321,"quote":"Srira Leon has nominated Professor Charles Cho Jalo, a distinguished international jurist for to be endorsed by and has been endorsed by the African Union and Echoas for election as a judge of the International Court of Justice.","topic":"Syria","kind":"fact"},{"t":1380,"quote":"Nearly 25 years ago, Syrian placed their trust in peace because they believed tomorrow could be different.","topic":"UN reform","kind":"fact"}],"promises":[{"t":630,"quote":"Syria will continue to advance that position","topic":"UN Security Council reform","kind":"promise"},{"t":1314,"quote":"We will also continue to to support the institutions of international justice.","topic":"Syria","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":5,"topic":null,"text":"The assembly will hear an address by his excellency Julius Mada Bon, president of the Republic of Serillion. I request protocol to escort his excellency and invite him to address the Mr. President of the General Assembly, Mr. Secretary General, Excellencies, distinguished ladies and I congratulate his excellency Khalil on his election as president of the 81st session of the General Assembly. President Raman assumes this responsibility at a moment that demands principled and steady leadership."},{"t":78,"topic":"UN leadership","text":"He has Syrian's full support. I pay tribute to his excellency secretary general Antonio Gutirez who is in the closing months of his He has served this organization with moral clarity and the courage to speak difficult truths. I also commend her excellency Amina J. the deputy secretary general, for her exemplary service and distinguished representation of Africa on the global Mr. President, nearly 25 years ago, Srielon completed disarmament and formally declared its civil war over."},{"t":144,"topic":"Sierra Leone peace","text":"The former declaration matters, of course, but peace became rare in more practical ways. In the families that returned home, in the communities that learned to live together again, in the citizens who chose the ballot, and in institutions that slowly returned back to confidence, the United Nations stood with us through disarmament, and the long work of peace building. So we know what international cooperation can make possible because we have lived it. The experience taught us that trust cannot be commanded by declaration. Trust grows when promises are honored."},{"t":209,"topic":"UN trust","text":"When the law protects everyone. when serve their people and when citizens can see a future for themselves. Serum brings that lesson to this assembly at a moment when trust between nations in institutions and in multilateral cooperation is under profound strain. In this year's theme, restoring trust, managing a united nation that delivers for all. The words for all carry its defining moral weight. The words for all ask not only whether United Nations can act but also its actions where they reach whose voices shape them and whose dignity they protect."},{"t":279,"topic":"International law","text":"An institution may act quickly and still fail those it was meant to serve. Delivery worthy of the UN charter must reach those farthest from power and recognize the equal worth of every nation and every human life. This is the standard by which the world will judge us all. Mr. President, that standard begins with trust. Trust is the currency of Trust is gained when the law protects the vulnerable as firmly as it restrains the powerful. International law must not change with geography or bend according to the identity of the accused. In the Middle East, the UN charter and international law must guide must guide us."},{"t":353,"topic":"Palestine-Israel","text":"Civilians must be protected, humanitarian access ensured, aggression and occupation ended, and freedom of navigation safeguarded. The inalienable right of the Palestinian people to self-determination must be realized through a viable state of Palestine living alongside the state of Israel in peace and in That same commitment to peace requires progress on nuclear disarmament and nonprololiferation through diplomacy. In Sudan, civilians continue to endure endure atrocities and displacement, underscoring the cost of delayed action. Syrial calls for their protection, unhindered humanitarian access, and a Sudaneseled political process that safeguards the country's sovereignty, unity, and territorial integrity."},{"t":427,"topic":"DRC conflict","text":"In the Eastern Democratic Republic of the Congo, agreements have not yet silenced the guns or allowed millions to return home. Across West Africa and the Saher, terrorism feeds on poverty, exclusion, unemployment, and weak institutions. These conflicts differ in origin and but they carry a common warning. Military action may contain a threat, but it cannot by itself build lasting When hunger, exclusion, and despair deepen, insecurity takes root. The connection between peace and development must therefore move from our resolutions into our budgets. In 2025, global military expenditure reached about 2.9 trillion United State dollars, the 11th consecutive annual increase."},{"t":503,"topic":"UN Security Council","text":"Of course, nations have legitimate security needs. But the speed with which the world finds resources for war compared to prevention and development law also depends on who has the voice in applying it. The credibility weakens when institutions entrusted with the law preserve an unequal distribution of The Security Council still reflects the world of 1945. Africa, home to more than 1.6 billion people and the subject of most of the council's work, still has no permanent That's not fair."},{"t":567,"topic":"UN Security Council reform","text":"Africa seeks its rightful place because the council cannot be fully legitimate or effective while an entire continent remains permanently absent from its highest level of decision No durable global solution on peace, climate, food, energy or technology can be built without African leadership. The common African position espoused in Ezinia consensus and such declaration calls for no fewer than two permanent seats with all the rights and privileges of permanent membership including the veto if it is retained and five non-permanent seats. As coordinator of the African Union Committee of 10, Syria will continue to advance that position."},{"t":637,"topic":"UN Security Council reform","text":"Years of intergovernmental negotiation without realizing the reform has tested the credibility of the process. Before this session concludes, member states should have a consolidated which we committed to in the past for the future. Sri speaks with the authority of service. During our time on the security council in 2024 2025, we worked as a voice of reason and a bridge across division. We convened the Security Council's first high level debate on redressing historical injustice against Africa, placed conflict related food insecurity at the center of its agenda, and with Guyana co-drafted unanimously adopted resolution 2807 on youth peace and security, strengthening young people's role in conflict prevention and peace building."},{"t":715,"topic":"UN Security Council reform","text":"Mr. President, representation becomes meaningful when it changes decisions and improves lives. The imbalance within the security council is also present in international financial institutions whose structures still bear the imprint of an earlier Developing countries need fairer voting power, stronger representation and increased capital within these institutions together with affordable finance, concessional resources and fairer debt treatment. They must also participate equally in shaping the rules of international Srielion therefore supports a UN framework convention on international tax cooperation through Echos serum we champion a development system that responds more effectively to Africa's priorities."},{"t":789,"topic":"African reparations","text":"Mr. President, restoring trust and delivering for all must also embrace the unfinished cause of reparatory In March, this assembly adopted a resolution led by Ghana and supported by the African Union and Caribbean community recognizing the trafficking and racialized charter enslavement of Africans as the gravest crime against For Sriraillon, this history is neither abstract nor From Bones Island in our own river estuary, thousands of Africans were forcibly transported across the Atlantic into enslavement. Freetown, our capital, would later become a home for formerly enslaved and liberated Africans."},{"t":858,"topic":"Reparatory justice","text":"This history is woven into our national the consequences did not end with Their legacy continues to be reflected in enduring disparities in wealth, power, and opportunity across our world. Reparatory justice is therefore not a plea for charity. It is a call for former apology, the return of cultural fair redress and guarantee of non Sriraelon stands with Africa, the Caribbean, and the wider African diaspora in advancing this cause, not to remain captive to the past, but to build a more just and equitable Mr."},{"t":925,"topic":"Africa minerals","text":"President, the same principle of fairness applies to Africa's critical Critical minerals are indispensable to the global energy transition. Yet too much value is still added Processing at source, fear value chains, technology transfer, and local industry would turn natural wealth into ski work, stronger economies, and hope for our young people. The green trans transition must not reproduce the extractive time of the For the youth, this is immediate. A young person without work, opportunity or a stake in the future becomes vulnerable to the recruiter, the smuggler and the dangerous journey across the Mediterranean. Jobs, skills, and dignity are therefore part of any serious policy for peace and Mr."},{"t":995,"topic":"Child marriage","text":"President, Srielon does not ask the world what it does not demand of itself. We carry these same principles into our work at home. Through feed salon, we are increasing domestic food production and strengthening food security. Through free quality education, we are widening the path for the circumstances of a child's birth. From a child's birth to the future that awaits that child. In 2024, we enacted the prohibition of child marriage act and subsequently championed the proclamation of 27 November as the international day for the elimination of child Ali and forced marriage. A girl in Sri Leon is no more or less precious than a car anywhere else in our beautiful world."},{"t":1062,"topic":"AI development","text":"protecting her childhood, education and freedom as part of what development is supposed to mean. A gas future like the future of every young person will be shaped by forces already remake remaking our world. Climate change, artificial intelligence and the energy transition. The meaning of for all becomes more urgent as we decide how these transformations will be Artificial intelligence can improve of course education, health, agriculture and public administration. It can also widen the inequality if infrastructure, knowledge and rule making remains concentrated in a few Developing nations must help shape the standards that will govern technologies affecting their people."},{"t":1125,"topic":"Climate finance","text":"Climate change presents the same moral question in harsher form. Who benefits? Who decides and who pays? In Shen on Srielon's southern coast, families watch the sea take their land, fishing grounds and the graves of their For them, climate change is the disappearance of home in the present. Those who contributed least to the climate crisis are bearing some of its gravest greatest cost. Accessible and predictable climate finance, support for adaptation and effective arrangement for loss and damage are obligations of justice. They are also investment in global Fairness in trans transformation depends on the institutions that govern it."},{"t":1189,"topic":"UN reform","text":"Syrielon therefore supports the UNH and wider reforms that make this organization more effective, accountable and responsive. Efficiency matters and reform must preserve the capacity to act. Mr. President, the choice of the next Secretary General offers another test of institutional effectiveness and equality. In 80 years, every Secretary General has been a man. The women put forward for this office have placed their competence beyond What remains is the will of the organization to live by the quality equality it asks of others and entrust a woman with his highest office."},{"t":1260,"topic":"Syria","text":"Mr. President, our insistence on a capable United Nations comes from experience for Syrian. This organization is part of our living history. It stood with us when our country was broken and helped us make peace durable. In this hall, a small state has the same vote as a great power. Imperfect as it is, that quality remains one of humanity's boldest promises. Syria will continue to contribute passionate to United Nations peace operations, uphold international law, support mediation and peace building, defend the rights of women and girls, and serve as a bridge wherever member states seek one. We will also continue to to support the institutions of international justice. In this regard, Srira Leon has nominated Professor Charles Cho Jalo, a distinguished international jurist for to be endorsed by and has been endorsed by the African Union and Echoas for election as a judge of the International Court of Justice."},{"t":1345,"topic":"UN reform","text":"We respectfully seek member state support on the 3rd of November. Mr. President, the United Nation was created in a world of une unequal power, yet it rests on a radical idea. Nations differ in size and strength, but their people do not differ in human A united nation that delivers for all makes that quality felt beyond this Nearly 25 years ago, Syrian placed their trust in peace because they believed tomorrow could be different. People around the world are asking something similar of us. Now they need reason to believe that cooperation still works, that law still matters, and that promises made here will be honored in their lives. Let this session give them that reason."},{"t":1413,"topic":"Ceremony","text":"The words for all should not remain at the end of this year's theme. that must become the measure of our work. I thank you all. On behalf of the assembly, I wish thank to the president of the republic of Srira Leon."}],"compare":[{"topic":"UN & its reform","share":0.4147,"mean":0.2037,"rank":16,"others":170},{"topic":"Africa","share":0.1066,"mean":0.023,"rank":16,"others":36},{"topic":"Syria","share":0.0655,"mean":0.0032,"rank":4,"others":7},{"topic":"Democratic Republic of the Congo","share":0.0575,"mean":0.0047,"rank":7,"others":6},{"topic":"Israel–Palestine","share":0.0547,"mean":0.0524,"rank":65,"others":76},{"topic":"International Law & Order","share":0.0524,"mean":0.0604,"rank":85,"others":102},{"topic":"Reparations","share":0.0517,"mean":0.0041,"rank":10,"others":13},{"topic":"Human Rights","share":0.051,"mean":0.0084,"rank":15,"others":24}]};
